// The full opt-in tool set would push the OCI image past the overlay2 128-layer
// limit (the PR Docker job loads the image with --load and runs it). The docker
// generator (scripts/generate-dockerfiles.ts) sets DATAMITSU_OCI_MINIMAL=1 to
// drop these apps from the image only — they stay installable on demand for
// every other command. The list began as the opt-in tool batch in tools.ts; dclint, droast and
// pinact have since left that batch but stay excluded here, since adding them back costs image layers.
//
// mmdc and slidev are here for a different reason: both drive a headless Chromium, and the image
// cannot run one. The browser was downloaded outside the app directory the image copies, so it
// never reached the image, and the base image (debian slim) lacks the ~50 system libraries it loads
// (graphics, audio, accessibility, X11 and more) and the fonts it renders with. Shipping the apps
// without a working browser only cost image size.
//
// dockle and skywalking-eyes are built from source with the Go runtime, and the arm64 image is built
// under emulation: with them, three Go builds share the emulated CPU and govulncheck ran past the
// 20-minute install timeout (alone it takes about 10). Neither was in the image before it moved to
// the Go runtime, since the registry had no binaries for them.
const ociExcludedApps = new Set([
  "alint",
  "blint",
  "cargo-deny",
  "dclint",
  "deptry",
  "dockle",
  "droast",
  "ls-lint",
  "mdsf",
  "mmdc",
  "pinact",
  "skywalking-eyes",
  "slidev",
  "sqruff",
  "ty",
  "zizmor",
]);

export const mapOfApps: BinManager.MapOfApps =
  facts().env.DATAMITSU_OCI_MINIMAL === "1"
    ? Object.fromEntries(Object.entries(allApps).filter(([key]) => !ociExcludedApps.has(key)))
    : allApps;
